import React from 'react';
import { PiggyBank, CreditCard, User } from 'lucide-react';
import { HomeIcon, CogIcon } from '@heroicons/react/24/outline';
import NavItem from './NavItem';

const Sidebar = () => {
  return (
    <div className="h-screen w-64 bg-indigo-600 text-white flex flex-col justify-between fixed">
      <div>
        <div className="flex items-center justify-center h-16 border-b border-indigo-500">
          <span className="text-2xl font-bold">R-Tracker</span>
        </div>
        <nav className="mt-4">
          <NavItem icon={<HomeIcon className="h-5 w-5" />} text="Dashboard" to="/dashboard" />
          <NavItem icon={<PiggyBank className="h-5 w-5" />} text="Budgets" to="/budgets" />
          <NavItem icon={<CreditCard className="h-5 w-5" />} text="Expenses" to="/expenses" />
          <NavItem icon={<User className="h-5 w-5" />} text="Profile" to="/profile" />
        </nav>
      </div>

      <div className="p-4 border-t border-indigo-500">
        <NavItem icon={<CogIcon className="h-5 w-5" />} text="Settings" />
      </div>
    </div>
  );
};

export default Sidebar;
